    "telq": "‘నేను ఫెమినిష్టుని, హ్యూమనిస్టు ఫెమినిస్టుని’ అని తనకు తానే గర్వంగా ప్రకటించుకున్న రచయిత్రి మల్లాది సుబ్బమ్మ. ఆంధ్రదేశంలో జరిగిన సారా వ్యతిరేక ఉద్యమంలో వారు చాలా చురుకుగా పాల్గొన్నారు. సారాను నిషేధించే వరకు విశ్రమించని ధీరురాలు. మల్లాదిసుబ్బమ్మ ట్రస్టును స్థాపించి ఆమె తన స్థిరాస్తులను తన పిల్లలకు కాకుండా ఆ ట్రస్టుకు రాసిచ్చారు. దానిని సామాజిక సేవకు అంకితం చేశారు. ఈమె కాలం 1924-2014\n‘హ్యూమనిష్టు ఫెమినిస్టు’ని అని ప్రకటించుకున్న రచయిత్రి",
