    "telq": "బహుదా నది ఒడ్డున పూర్వం ‘పొత్తపినాడు’ అనే ప్రాంతంలో ‘ఉడుమూరు’ అనే బోయపల్లె ఉండేది. ఆ పల్లె రాజు నాథ నాథుడు. అతని భార్య తందె. వీరికిజన్మించిన కొడుకు తిన్నడు. ఒకనాడు తిన్నడు వేటకు వెళ్ళాడు. వేటాడి, అలసిపోయి ఒక పొగడ చెట్టుకింద నిద్రపోయాడు.\nతిన్నని తల్లిదండ్రులు",
