    "telq": "కురుక్షేత్రయుద్ధవిజేత అయిన ధర్మరాజు హస్తినాపుర రాజ్యపాలన సాగిస్తున్నాడు. కాలంతో వచ్చిన మార్పుల్ని గమనిస్తున్నాడు. కొంతకాలానికి ఉత్తమగతిని పొందాలని సంకల్పించాడు. అందుకు మహాప్రస్థానమే అత్యుత్తమ సాధనంగా తోచింది. అందుకోసం తమ్ములను ఒప్పించాడు. పరీక్షిత్తుకు పట్టం కట్టి తన బరువు బాధ్యతల నుండి విడుదల పొందాడు. రాజభోగాలు వదిలి నారచీరలు కట్టి తమ్ములతో సహా మహాప్రస్థానానికి బయలుదేరారు. ధర్మరాజు మహాప్రస్థానానికి వెళ్ళేటప్పుడు రాజ్యమును వీరికి అప్పగించాడు",
